import json, re
from pathlib import Path

coach_file = Path('/root/DATA/products/CoachForce.json')
personal_file = Path('/root/DATA/products/PersonalizeForce.json')

coach = json.loads(coach_file.read_text())
personal = json.loads(personal_file.read_text())

# Q1: authors + key reviewers for CoachForce Market Research Report
# Authors from documents of type "Market Research Report"
authors = []
for doc in coach.get('documents', []):
    if doc.get('type') == 'Market Research Report':
        a = doc.get('author')
        if a and a not in authors:
            authors.append(a)

# Key reviewers: users who responded between initial share and updated share in planning-CoFoAIX
slack_msgs = coach.get('slack', [])
# find indices
start_idx = end_idx = None
for i, item in enumerate(slack_msgs):
    msg = item.get('Message', {}).get('User', {})
    text = msg.get('text', '')
    if 'cofoaix_market_research_report' in text:
        start_idx = i
    if 'final_cofoaix_market_research_report' in text:
        end_idx = i
        break

reviewers = []
if start_idx is not None and end_idx is not None:
    for item in slack_msgs[start_idx+1:end_idx]:
